@push('scripts')
<script>
document.querySelectorAll('.cash-count').forEach((input) => input.addEventListener('input', () => { let total = 0; document.querySelectorAll('.cash-count').forEach((field) => total += Number(field.value || 0) * Number(field.dataset.denomination)); document.getElementById('count-total').textContent = `Bs ${total.toFixed(2)}`; }));
const paymentHost = document.getElementById('payment-lines'); let paymentIndex = 0;
function addPaymentLine(amount = '') { const fragment = document.getElementById('payment-line-template').content.cloneNode(true); const row = fragment.querySelector('.payment-line'); const index = paymentIndex++; row.querySelector('.payment-method').name = `payments[${index}][method]`; row.querySelector('.payment-amount').name = `payments[${index}][amount]`; row.querySelector('.payment-amount').value = amount; row.querySelector('.payment-reference').name = `payments[${index}][reference]`; const key = document.createElement('input'); key.type = 'hidden'; key.name = `payments[${index}][idempotency_key]`; key.value = crypto.randomUUID(); row.appendChild(key); row.querySelector('.remove-payment').addEventListener('click', () => { if (paymentHost.children.length > 1) row.remove(); }); paymentHost.appendChild(fragment); }
document.getElementById('paymentModal')?.addEventListener('show.bs.modal', (event) => { const button = event.relatedTarget; paymentHost.replaceChildren(); paymentIndex = 0; document.getElementById('payment-sale-id').value = button.dataset.saleId; document.getElementById('payment-sale-number').textContent = button.dataset.saleNumber; document.getElementById('payment-balance').textContent = `Bs ${Number(button.dataset.balance).toFixed(2)}`; addPaymentLine(button.dataset.balance); });
document.getElementById('add-payment-line')?.addEventListener('click', () => addPaymentLine());
document.getElementById('mixed-payment-form')?.addEventListener('submit', (event) => { let total = 0; document.querySelectorAll('.payment-line').forEach((row) => { const method = row.querySelector('.payment-method').value; const reference = row.querySelector('.payment-reference'); reference.required = method !== 'cash'; total += Number(row.querySelector('.payment-amount').value || 0); }); if (!event.currentTarget.checkValidity()) { event.preventDefault(); event.currentTarget.reportValidity(); return; } const balance = Number(document.getElementById('payment-balance').textContent.replace('Bs ', '')); if (total > balance + .001) { event.preventDefault(); alert('La suma de pagos supera el saldo pendiente.'); } });
</script>
@endpush
